import type { CourseContent, Exercise, LessonContent, UnitContent } from "../types.js";
import { concept, exam, lesson, mcq, unit } from "../builders.js";
import { expandCourse } from "./factory.js";

export type Choice = {
  id: string;
  promptUk: string;
  promptEn: string;
  options: string[];
  optionsEn: string[];
  correctIndex: number;
  explanationUk: string;
  explanationEn: string;
};

export function choice(row: Choice): Exercise {
  return {
    ...mcq(row.id, row.promptUk, row.promptEn, row.options, row.correctIndex, {
      explanationUk: row.explanationUk,
      explanationEn: row.explanationEn,
    }),
    optionsEn: row.optionsEn,
  };
}

export function taught(
  slug: string,
  titleUk: string,
  titleEn: string,
  conceptUk: string,
  conceptEn: string,
  exercises: Exercise[],
): LessonContent {
  return lesson(slug, titleUk, titleEn, 4, false, [
    concept(`${slug}-concept`, titleUk, titleEn, { uk: conceptUk, en: conceptEn }),
    ...exercises,
  ]);
}

