const PRACTICE_UNITS: Record<string, UnitContent> = {
  go_fundamentals: goService,
  web_accessibility: accessibleFlow,
  rest_api_design: retrySafeApi,
  frontend_performance: performanceTriage,
  browser_web_apis: browserSearch,
};

export function expandAppliedCapstones(course: CourseContent): CourseContent {
  const practicalUnit = PRACTICE_UNITS[course.slug];
  return practicalUnit ? expandCourse(course, {}, [practicalUnit]) : course;
}
